// Pictures and files for the fields that hold their address. The domain keeps only the address
// (`/cms/api/media/file/photo.jpg`); the bytes belong to the content system, which serves them from
// that address. `POST <base>/upload/<collection>` takes one file with a description, checks it, and
// has the content system keep it the way its own admin would: the same collection, the same
// description field, the same address back. The editor never keeps a file of its own, and the page
// that shows the site never changes.
//
// Every request reaching here is already authenticated by app.ts. The content system is asked as the
// person: a short account token, signed with the secret it shares with the host, is exchanged at its
// own sign-in endpoint for a session, which is remembered for a few minutes per person. A person the
// content system does not admit is refused there, in its words.
//
// What is accepted is decided by the file's own first bytes (pictures: JPEG, PNG, WebP, GIF, AVIF;
// files: PDF), never by the type or the name the browser sent; the size is capped by the Editor row;
// the description is required, because the content system requires it. The name the file is kept
// under is made from the one it had, with anything but letters, digits, dot, dash and underscore
// replaced, so it is safe in an address.
import { accountToken } from "@hecks/client";

import { authSecret } from "./auth/membership.ts";
import { EDITOR } from "./config.ts";
import { boundaryOf, parts } from "./files/multipart.ts";
import { EXTENSION_OF, isPdf, sniff } from "./files/sniff.ts";
import { SCHEMA } from "./schema.ts";
import type { Aggregate, Attr } from "./schema.ts";

/** The room the form's framing takes beyond the file's own size cap. */
const OVERHEAD_BYTES = 65_536;

/** How long a person's session with the content system is remembered. */
const SESSION_MS = 5 * 60_000;

const TYPE_WORDS = { image: "a JPEG, PNG, WebP, GIF or AVIF picture", pdf: "a PDF file" } as const;

export interface UploadOptions {
  /** The content system's address, when not read from the environment variable the Editor row names. */
  url?: string;
  fetch?: typeof fetch;
  secret?: string;
  now?: () => number;
}

const json = (value: unknown, status = 200): Response =>
  new Response(JSON.stringify(value), { status, headers: { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" } });

const refuse = (status: number, error: string): Response => json({ error }, status);

/** What the collections the schema's fields upload to accept: `image` or `pdf`. */
export function collections(): Map<string, "image" | "pdf"> {
  const found = new Map<string, "image" | "pdf">();
  const visit = (attrs: Attr[]): void => {
    for (const attr of attrs) if (attr.upload) found.set(attr.upload.collection, attr.upload.accept);
  };
  for (const agg of SCHEMA.aggregates as Aggregate[]) {
    visit(agg.attributes);
    for (const command of agg.commands) visit(command.attributes);
    for (const parts of Object.values(agg.valueObjects)) visit(parts);
  }
  return found;
}

/** The file's name made safe, with the extension its own bytes say. */
export function safeName(given: string | null, extension: string): string {
  const base = (given ?? "").split(/[\\/]/).pop() ?? "";
  const stem = base.replace(/\.[A-Za-z0-9]{1,5}$/, "").replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[-.]+|[-.]+$/g, "").slice(0, 80);
  return `${stem || "upload"}.${extension}`;
}

/** The body, or null when it is larger than `limit`: no more than `limit` bytes are ever held. */
async function readBounded(request: Request, limit: number): Promise<Uint8Array | null> {
  const declared = Number(request.headers.get("content-length") ?? 0);
  if (declared > limit) return null;
  const reader = request.body?.getReader();
  const chunks: Uint8Array[] = [];
  let size = 0;
  while (reader) {
    const { done, value } = await reader.read();
    if (done) break;
    size += value.length;
    if (size > limit) {
      await reader.cancel();
      return null;
    }
    chunks.push(value);
  }
  return Buffer.concat(chunks);
}

const megabytes = (bytes: number): string => `${Math.max(1, Math.round(bytes / 1_048_576))} MB`;

/** The refusal's words from a content-system answer, or the fallback. */
async function reasonOf(res: Response, fallback: string): Promise<string> {
  const body = (await res.json().catch(() => null)) as { errors?: { message?: string }[]; message?: string } | null;
  return body?.errors?.[0]?.message ?? body?.message ?? fallback;
}

/**
 * The content system as the signed-in person: its address and a session of theirs, from its own
 * sign-in endpoint, remembered for a few minutes per person. Uploads and the library share it.
 */
export function contentSystem(options: UploadOptions = {}) {
  const settings = EDITOR.upload;
  const send = options.fetch ?? fetch;
  const now = options.now ?? Date.now;
  const sessions = new Map<string, { cookie: string; until: number }>();

  const address = (): string => ((options.url ?? (settings ? process.env[settings.env] || settings.default : "")) as string).replace(/\/+$/, "");

  /** The person's session cookie at the content system, from its own sign-in endpoint. */
  async function sessionFor(email: string): Promise<string | null> {
    const hit = sessions.get(email);
    if (hit && hit.until > now()) return hit.cookie;
    const secret = options.secret ?? authSecret();
    if (!settings || !secret) return null;
    const token = accountToken(secret, email, 60);
    const res = await send(`${address()}${settings.api}/sso?token=${encodeURIComponent(token)}`, {
      redirect: "manual",
      signal: AbortSignal.timeout(EDITOR.timeoutMs),
    });
    const cookie = res.headers.getSetCookie().map((line) => line.split(";")[0]).find((pair) => /-token=/.test(pair));
    if (!cookie) return null;
    sessions.set(email, { cookie, until: now() + SESSION_MS });
    return cookie;
  }

  return { settings, send, address, sessionFor };
}

/** The handler of `POST <base>/upload/<collection>`, given the signed-in person's email. */
export function uploadHandler(options: UploadOptions = {}) {
  const { settings, send, address, sessionFor } = contentSystem(options);
  const accepted = collections();

  return async (email: string, request: Request, collection: string): Promise<Response> => {
    const accepts = accepted.get(collection);
    if (!settings || !accepts) return refuse(404, "No such place to keep files.");
    if (request.method !== "POST") return refuse(405, "Send a file with POST.");
    const limit = EDITOR.mediaMaxBytes;
    const body = await readBounded(request, limit + OVERHEAD_BYTES);
    if (!body) return refuse(413, `A file may be at most ${megabytes(limit)}.`);
    const boundary = boundaryOf(request.headers.get("content-type"));
    const sections = boundary ? parts(body, boundary) : [];
    const file = sections.find((part) => part.name === "file" && part.filename !== null);
    if (!file || file.data.length === 0) return refuse(400, "Choose a file to upload.");
    if (file.data.length > limit) return refuse(413, `A file may be at most ${megabytes(limit)}.`);
    const mime = accepts === "pdf" ? (isPdf(file.data) ? "application/pdf" : null) : sniff(file.data);
    if (!mime) return refuse(415, `Only ${TYPE_WORDS[accepts]} can be added here.`);
    const alt = Buffer.from(sections.find((part) => part.name === "alt")?.data ?? []).toString("utf8").trim();
    if (alt === "") return refuse(422, accepts === "pdf" ? "Say what this file is before adding it." : "Describe the picture before adding it.");
    if (alt.length > 300) return refuse(422, "Keep the description to 300 characters.");

    try {
      const cookie = await sessionFor(email);
      if (!cookie) return refuse(403, "The content system did not accept your sign-in, so the file was not kept. Sign in again and try once more.");
      const form = new FormData();
      form.set("file", new Blob([file.data as BlobPart], { type: mime }), safeName(file.filename, mime === "application/pdf" ? "pdf" : EXTENSION_OF[mime]));
      form.set("_payload", JSON.stringify({ alt }));
      const res = await send(`${address()}${settings.api}/${collection}`, {
        method: "POST",
        headers: { Cookie: cookie },
        body: form,
        signal: AbortSignal.timeout(EDITOR.timeoutMs * 6),
      });
      if (!res.ok) return refuse(res.status === 401 || res.status === 403 ? 403 : 422, await reasonOf(res, "The content system did not keep the file."));
      const made = ((await res.json().catch(() => null)) as { doc?: { filename?: string } } | null)?.doc;
      if (!made?.filename) return refuse(502, "The content system kept the file but did not say where. Check the list of files there.");
      return json({ address: `${settings.api}/${collection}/file/${encodeURIComponent(made.filename)}`, alt, filename: made.filename, mime }, 201);
    } catch {
      return refuse(502, "The content system could not be reached, so the file was not kept. Try again in a moment.");
    }
  };
}

/** Whether a path is an upload, for the size limit the server reads a body with. */
export const isUploadPath = (path: string): boolean => path.startsWith(`${EDITOR.basePath}/upload/`);
